export type TestStatus = 'checked' | 'demo';

// A generic multi-section timing window: one or more Question.section values
// that share a single countdown, auto-submitting into the next group (or
// ending the test, if last) when time runs out, with no way back into an
// already-submitted group. `sectionDuration`/`sectionDurations` below only
// model a 1-section-per-window timer; this covers exams (e.g. MHT CET, where
// Physics and Chemistry share one 90-minute window before Mathematics gets
// its own 90 minutes) where a window spans more than one section.
export interface TimingGroup {
  sections: string[];
  duration: number;
}

export interface TestConfig {
  id: string;
  name: string;
  kind: 'full-length' | 'sectional' | 'practice' | 'quick' | 'topic' | 'difficulty';
  status: TestStatus;
  duration: number;
  sectionDuration?: number;
  sectionDurations?: number[];
  timingGroups?: TimingGroup[];
  marksPerCorrect: number;
  negativeMarking: number;
  scoringNote?: string;
  section?: string;
  checkedOn?: string;
}

export interface StagePattern {
  status: 'official' | 'review-pending';
  cycle?: string;
  sections: string[];
  totalQuestions?: number;
  totalMarks?: number;
  duration?: number;
  negativeMarking?: number | string;
  sectionBreakdown?: {
    name: string;
    questions: number;
    marks: number;
    duration?: number;
  }[];
  timerNote?: string;
  note?: string;
  sourceUrl?: string;
  checkedOn?: string;
}

export interface TestStage {
  id: string;
  name: string;
  pattern: StagePattern;
  tests: TestConfig[];
}

export interface ExamConfig {
  slug: ExamSlug;
  name: string;
  /** Shorter variant of `name`, used only in <title> tags where the full name would push past ~60-65 characters. Falls back to `name` when absent. */
  shortName?: string;
  fullName: string;
  category: 'SSC' | 'Banking' | 'Railways' | 'Civil Services' | 'Engineering' | 'English Proficiency' | 'Study Abroad' | 'Finance' | 'Defence' | 'Law' | 'Management';
  stages: TestStage[];
}

